package com.example.microsave.contribution.entity;
import com.example.microsave.member.entity.Member; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDate;
@Entity @Table(name="contributions") public class Contribution { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="member_id",nullable=false) private Member member; @Column(nullable=false,precision=12,scale=2) private BigDecimal amount; @Column(nullable=false) private LocalDate contributionDate; @Column(nullable=false) private Integer weekNumber; @Column(length=300) private String remarks; public Contribution(){} public Long getId(){return id;} public Member getMember(){return member;} public void setMember(Member v){member=v;} public BigDecimal getAmount(){return amount;} public void setAmount(BigDecimal v){amount=v;} public LocalDate getContributionDate(){return contributionDate;} public void setContributionDate(LocalDate v){contributionDate=v;} public Integer getWeekNumber(){return weekNumber;} public void setWeekNumber(Integer v){weekNumber=v;} public String getRemarks(){return remarks;} public void setRemarks(String v){remarks=v;} }
